// Shared building blocks for every page: database, formatting, tables, charts,
// panels, links and the detail drawer. Owned by the integrator; page owners
// import from here and do not edit this file.
import { PGlite } from '../lib/pglite/index.js'

const $ = (s, r = document) => r.querySelector(s)
const h = (tag, attrs = {}, ...kids) => {
  const el = document.createElement(tag)
  for (const [k, v] of Object.entries(attrs ?? {})) {
    if (v === false || v == null) continue
    if (k.startsWith('on')) el.addEventListener(k.slice(2), v)
    else if (k === 'class') el.className = v
    else if (k === 'html') el.innerHTML = v
    else el.setAttribute(k, v)
  }
  for (const kid of kids.flat()) if (kid != null && kid !== false) el.append(kid)
  return el
}

// ---------- Database ----------
export let db
const decode = async (path) => {
  const text = await fetch(path).then((r) => r.text())
  return Uint8Array.from(atob(text.trim()), (c) => c.charCodeAt(0))
}
const boot = async () => {
  const say = (t) => { $('#bootmsg').textContent = t }
  say('Loading PostgreSQL in your browser')
  const [fsBundle, snapshot] = await Promise.all([decode('./lib/pglite/pglite-data.b64.txt'), decode('./data/tdf-db.b64.txt')])
  say('Opening the race database')
  db = await PGlite.create({
    fsBundle: new Blob([fsBundle]),
    loadDataDir: new Blob([snapshot], { type: 'application/x-gzip' }),
  })
}
const q = async (sql) => (await db.query(sql)).rows
const str = (v) => `'${String(v).replace(/'/g, "''")}'`

// ---------- Formatting ----------
const pad = (n) => String(n).padStart(2, '0')
const fmtTime = (s) => {
  if (s == null) return ''
  s = Math.round(Number(s))
  const H = Math.floor(s / 3600), M = Math.floor((s % 3600) / 60), S = s % 60
  return `${H}h${pad(M)}'${pad(S)}"`
}
const fmtGap = (s) => {
  if (s == null) return ''
  s = Math.round(Number(s))
  if (s === 0) return '0"'
  const a = Math.abs(s), H = Math.floor(a / 3600), M = Math.floor((a % 3600) / 60), S = a % 60
  const sign = s < 0 ? '−' : '+'
  if (H) return `${sign}${H}h${pad(M)}'${pad(S)}"`
  return M ? `${sign}${M}'${pad(S)}"` : `${sign}${S}"`
}
const fmtNum = (v, d = 0) => (v == null ? '' : Number(v).toLocaleString('en-GB', { minimumFractionDigits: d, maximumFractionDigits: d }))
const fmtInt = (v) => fmtNum(v)
const shortTeam = (t) => t.replace(/ TEAM EMIRATES XRG| \| LEASE A BIKE| - BORA - HANSGROHE/g, '').replace(/^TEAM /, '')
const TERRAIN = ['Flat', 'Hilly', 'Mountain', 'ITT']
const GLYPH = {
  Flat: '<path d="M1 9h18" fill="none" stroke="currentColor" stroke-width="2"/>',
  Hilly: '<path d="M1 11q4-9 8-4t10-3" fill="none" stroke="currentColor" stroke-width="2"/>',
  Mountain: '<path d="M1 13 7 3l3 5 3-3 6 8" fill="none" stroke="currentColor" stroke-width="2"/>',
  ITT: '<circle cx="10" cy="7" r="5.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M10 4v3h3" fill="none" stroke="currentColor" stroke-width="1.6"/>',
}
const terrainVar = (t) => `var(--s${TERRAIN.indexOf(t) + 1})`
const terrain = (t) => h('span', { class: 'chip' },
  h('span', { style: `color:${terrainVar(t)};display:inline-flex`, html: `<svg viewBox="0 0 20 14" aria-hidden="true">${GLYPH[t]}</svg>` }), t)

// ---------- Tables ----------
function table({ cols, rows, onRow, hit, limit, total }) {
  let sort = null, dir = 1, shown = limit ?? Infinity
  const wrap = h('div', { class: 'tw' })
  const draw = () => {
    let list = rows
    if (sort) {
      const c = cols.find((x) => x.k === sort)
      const val = c.sortBy ?? ((r) => r[sort])
      list = [...rows].sort((a, b) => {
        const x = val(a), y = val(b)
        if (x == null) return 1
        if (y == null) return -1
        return (typeof x === 'string' && isNaN(x) ? String(x).localeCompare(y) : Number(x) - Number(y)) * dir
      })
    }
    const head = h('tr', {}, cols.map((c) => h('th', {
      class: `${c.n ? 'n' : ''}`, title: c.hint ?? false,
      onclick: () => { if (sort === c.k) dir = -dir; else { sort = c.k; dir = 1 } draw() },
    }, c.l + (sort === c.k ? (dir > 0 ? ' ▲' : ' ▼') : ''))))
    const body = list.slice(0, shown).map((r) => h('tr', {
      class: `${hit?.(r) ? 'hit' : ''}`, style: onRow ? 'cursor:pointer' : false, onclick: onRow ? () => onRow(r) : false,
    }, cols.map((c) => h('td', { class: c.n ? 'n' : '' }, c.f ? c.f(r[c.k], r) : (r[c.k] ?? '')))))
    const foot = total ? h('tr', { class: 'total' }, cols.map((c) => h('td', { class: c.n ? 'n' : '' }, total[c.k] ?? ''))) : null
    wrap.replaceChildren(h('table', {}, h('thead', {}, head), h('tbody', {}, body, foot)))
    if (list.length > shown) wrap.append(h('div', { style: 'padding-top:6px' }, h('button', { class: 'btn', onclick: () => { shown = Infinity; draw() } }, `Show all ${list.length}`)))
  }
  draw()
  return wrap
}
const riderCol = (k = 'rider_name') => ({ k, l: 'Rider', f: (v, r) => h('button', { class: 'lnk', onclick: (e) => { e.stopPropagation(); open({ t: 'rider', id: r.rider_key }) } }, v) })
const teamLink = (name, key) => h('button', { class: 'lnk', style: 'font-weight:400', onclick: (e) => { e.stopPropagation(); open({ t: 'team', id: key }) } }, shortTeam(name))
const teamCol = () => ({ k: 'team_name', l: 'Team', f: (v, r) => teamLink(v, r.team_key) })
const natLink = (code) => h('button', { class: 'lnk mono', style: 'font-weight:400', onclick: (e) => { e.stopPropagation(); open({ t: 'nation', id: code }) } }, code)
const stageLink = (id) => h('button', { class: 'lnk mono', onclick: (e) => { e.stopPropagation(); open({ t: 'stage', id }) } }, `S${pad(id)}`)

// ---------- Charts ----------
const live = new Set()
const tokens = () => {
  const c = getComputedStyle(document.documentElement)
  const t = {}
  for (const k of ['ink', 'ink2', 'muted', 'line', 'axis', 'surface', 'sunken', 'jaune']) t[k] = c.getPropertyValue(`--${k}`).trim()
  t.s = [1, 2, 3, 4, 5, 6, 7, 8].map((i) => c.getPropertyValue(`--s${i}`).trim())
  t.font = c.getPropertyValue('--body').trim()
  t.mono = c.getPropertyValue('--mono').trim()
  return t
}
const baseOpt = (t) => ({
  textStyle: { fontFamily: t.font, color: t.ink2 },
  animationDuration: 260,
  tooltip: { backgroundColor: t.surface, borderColor: t.axis, textStyle: { color: t.ink, fontFamily: t.font, fontSize: 13 }, confine: true },
  legend: { textStyle: { color: t.ink2 }, icon: 'roundRect', itemWidth: 12, itemHeight: 8, top: 0 },
})
const axisStyle = (t) => ({
  axisLine: { lineStyle: { color: t.axis } }, axisTick: { show: false },
  axisLabel: { color: t.muted, fontFamily: t.mono, fontSize: 11 },
  splitLine: { lineStyle: { color: t.line } },
})
function chart(optionFn, { height = 320, onClick } = {}) {
  const el = h('div', { class: 'chart', style: `height:${height}px` })
  const entry = { el, inst: null, draw: () => {
    entry.inst ??= echarts.init(el)
    entry.inst.setOption(optionFn(tokens()), true)
  } }
  live.add(entry)
  const ro = new ResizeObserver(() => { if (el.clientWidth) { if (!entry.inst) entry.draw(); else entry.inst.resize() } })
  ro.observe(el)
  entry.ro = ro
  requestAnimationFrame(() => {
    if (el.isConnected && el.clientWidth) {
      if (!entry.inst) entry.draw()
      if (onClick) entry.inst.on('click', onClick)
    } else if (onClick) {
      const wait = setInterval(() => { if (entry.inst) { entry.inst.on('click', onClick); clearInterval(wait) } if (!el.isConnected) clearInterval(wait) }, 200)
    }
  })
  return el
}
const sweep = () => { for (const e of live) if (!e.el.isConnected) { e.ro.disconnect(); e.inst?.dispose(); live.delete(e) } }
const redrawAll = () => { sweep(); for (const e of live) if (e.inst) e.draw() }
matchMedia('(prefers-color-scheme: dark)').addEventListener('change', redrawAll)
new MutationObserver(redrawAll).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] })

// ---------- Panels ----------
function panel(parent, { title, tag, note, span, sql }) {
  const body = h('div', { class: 'pbody' })
  const ctrl = h('div', { class: 'ctrl', hidden: true })
  const noteEl = note ? h('div', { class: 'pnote' }, note) : null
  const p = { sql, body, ctrl }
  const head = h('div', { class: 'phead' }, h('h2', {}, title), tag && h('span', { class: 'tag' }, tag), h('span', { class: 'spacer' }),
    sql !== undefined && h('button', { class: 'sqlbtn', onclick: () => toConsole(p.sql) }, 'Open SQL'))
  const el = h('section', { class: `panel ${span ? `s${span}` : ''}` }, head, noteEl, ctrl, body)
  parent.append(el)
  p.el = el
  p.controls = (...nodes) => { ctrl.hidden = false; ctrl.append(...nodes) }
  return p
}
function seg(options, value, onChange) {
  const el = h('div', { class: 'seg', role: 'group' })
  const draw = () => el.replaceChildren(...options.map(([v, l]) => h('button', { 'aria-pressed': String(v === value), onclick: () => { value = v; draw(); onChange(v) } }, l)))
  draw()
  return el
}
const select = (options, value, onChange, attrs = {}) => {
  const el = h('select', { ...attrs, onchange: (e) => onChange(e.target.value) }, options.map(([v, l]) => h('option', { value: v, selected: v === value ? 'selected' : false }, l)))
  return el
}

// ---------- Shared lookups ----------
const S = {}
const loadLookups = async () => {
  S.stages = await q(`SELECT stage_id, stage_key, stage_date::text, terrain, distance_km::float8 AS km, route, start_location, finish_location, start_country, finish_country, race_week FROM dim_stage ORDER BY stage_id`)
  S.mountain = S.stages.filter((s) => s.terrain === 'Mountain').map((s) => s.stage_id)
  S.finishers = await q(`SELECT rider_key, rider_name, gc_rank, team_name FROM v_gc ORDER BY gc_rank`)
  S.riders = await q(`SELECT rider_key, rider_name, team_name FROM dim_rider ORDER BY rider_name`)
  S.teams = await q(`SELECT team_key, team_name FROM dim_team ORDER BY team_name`)
  const [c] = await q(`SELECT (SELECT COUNT(*) FROM dim_stage) stages, (SELECT SUM(distance_km) FROM dim_stage)::float8 km, (SELECT COUNT(*) FROM dim_rider) riders, (SELECT COUNT(*) FROM dim_rider WHERE race_status='Finished') finishers, (SELECT COUNT(*) FROM dim_team) teams, (SELECT COUNT(*) FROM fact_results) facts`)
  S.counts = c
  $('#facts').replaceChildren(...[`${c.stages} stages`, `${fmtNum(c.km, 1)} km`, `${c.riders} riders`, `${c.teams} teams`, `${fmtNum(c.facts)} result rows`].map((t) => h('span', {}, t)))
}
const riderColor = (key, list) => `var(--s${(list.indexOf(key) % 8) + 1})`

// ---------- Drawer: rider, team, stage and nation dossiers ----------
// Each module file registers the dossier it owns, e.g. VIEWS.rider = riderView.
const VIEWS = {}
const stack = []
const open = (view) => { stack.push(view); drawDrawer() }
const closeDrawer = () => { stack.length = 0; $('#drawer').hidden = true; $('#scrim').hidden = true; sweep() }
$('#scrim').addEventListener('click', closeDrawer)
addEventListener('keydown', (e) => { if (e.key === 'Escape' && stack.length) closeDrawer() })
async function drawDrawer() {
  const d = $('#drawer')
  const view = stack.at(-1)
  const title = h('h2', {}, '')
  const body = h('div', { class: 'dbody' })
  d.replaceChildren(h('div', { class: 'dhead' },
    stack.length > 1 && h('button', { onclick: () => { stack.pop(); drawDrawer() } }, '← Back'),
    title, h('button', { onclick: closeDrawer, 'aria-label': 'Close details' }, 'Close')), body)
  d.hidden = false; $('#scrim').hidden = false
  sweep()
  await VIEWS[view.t](view.id, title, body)
}
const kv = (pairs) => h('div', { class: 'kv' }, pairs.map(([b, s]) => h('div', {}, h('b', {}, b), h('span', {}, s))))
const sqlShow = (sql) => h('details', {}, h('summary', { style: 'cursor:pointer;font-size:13px;color:var(--ink2)' }, 'SQL behind this view'), h('pre', { class: 'sqlshow' }, sql),
  h('button', { class: 'sqlbtn', style: 'margin-top:6px', onclick: () => { closeDrawer(); toConsole(sql) } }, 'Open in console'))


// Set by app.js, which owns the tabs and the console page.
const hooks = { toConsole: () => {} }
const toConsole = (sql) => hooks.toConsole(sql)

export {
  $, h, boot, q, str, pad, fmtTime, fmtGap,
  fmtNum, fmtInt, shortTeam, TERRAIN, GLYPH, terrainVar, terrain, table,
  riderCol, teamLink, teamCol, natLink, stageLink, live, tokens, baseOpt,
  axisStyle, chart, sweep, redrawAll, panel, seg, select, S,
  loadLookups, riderColor, open, closeDrawer, VIEWS, kv, sqlShow, hooks,
  toConsole,
}
